import java.util.Optional;

public class Main {
    static Optional<String> find(String key) {
        if (key.equals("{k1}")) {
            return Optional.of("{v1}");
        }
        if (key.equals("{k2}")) {
            return Optional.of("{v2}");
        }
        return Optional.empty();
    }

    public static void main(String[] args) {
        find("{k1}").ifPresent(v -> System.out.println("找到的是 " + v));
        find("{k2}").ifPresent(v -> System.out.println("找到的是 " + v));
        find("{k3}").ifPresent(v -> System.out.println("找到的是 " + v));
    }
}
